nativeSource:
{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
}
|group#visual| "Schema interchange fabric" { layout: grid; columns: repeat(1); gap: 44; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |group#l1| "Source models" { layout: grid; columns: repeat(1); gap: 24; padding: 22; fill: --gray-wash; stroke: --gray-deep; color: --gray-deep; stroke-width: 1; } [
    |box#n1| "Native schema" { width: 240; }
    |box#n2| "Authored model" { width: 240; }
  ]
  |group#l2| "Portable metadata" { layout: grid; columns: repeat(1); gap: 24; padding: 22; fill: --gray-wash; stroke: --gray-deep; color: --gray-deep; stroke-width: 1; } [
    |box#n3| "UMF" { width: 240; } [
      |cell#detail| "Common metadata + native details"
    ]
  ]
  |group#l3| "Metadata consumers" { layout: grid; columns: repeat(1); gap: 24; padding: 22; fill: --gray-wash; stroke: --gray-deep; color: --gray-deep; stroke-width: 1; } [
    |box#n4| "Generators" { width: 240; }
    |box#n5| "Forms" { width: 240; }
    |box#n6| "AI context" { width: 240; }
  ]
]
